"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.parse
import urllib.request


def _get_window(url, cursor, limit):
    """Fetch one window, retrying transient 429s with the identical request."""
    query = {"limit": limit}
    if cursor is not None:
        query["cursor"] = cursor
    request_url = f"{url}?{urllib.parse.urlencode(query)}"
    while True:
        try:
            with urllib.request.urlopen(request_url, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code != 429:
                raise
            retry_after = exc.headers.get("Retry-After", "1")
            try:
                delay = float(retry_after)
            except ValueError:
                delay = 1.0
            time.sleep(max(delay, 0))


def fetch_payouts(base_url):
    """Return every payout from the v2 export, exactly once, in order."""
    url = f"{base_url}/v2/payouts"
    payouts = []
    seen = set()
    cursor = None
    while True:
        window = _get_window(url, cursor, 1000)
        for payout in window["payouts"]:
            payout_id = payout["id"]
            if payout_id not in seen:
                seen.add(payout_id)
                payouts.append(payout)
        if window["drained"]:
            break
        cursor = window["cursor"]
    return payouts


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()
    payouts = fetch_payouts(args.base_url.rstrip("/"))
    with open(args.out, "w") as f:
        for p in payouts:
            f.write(json.dumps(p) + "\n")
    print(f"synced {len(payouts)} payouts")


if __name__ == "__main__":
    main()

